import localFont from 'next/font/local';

/**
 * Self-hosted woff2 subsets generated by `npm run brand:fonts` (06 §3).
 * Exposed as CSS variables consumed by the Tailwind theme (globals.css: --font-sans/display/brand).
 */
export const poppins = localFont({
  src: [
    { path: './fonts/poppins-400.woff2', weight: '400', style: 'normal' },
    { path: './fonts/poppins-500.woff2', weight: '500', style: 'normal' },
    { path: './fonts/poppins-600.woff2', weight: '600', style: 'normal' },
    { path: './fonts/poppins-700.woff2', weight: '700', style: 'normal' },
  ],
  variable: '--font-poppins',
  display: 'swap',
  preload: true,
  fallback: ['ui-sans-serif', 'system-ui', 'Segoe UI', 'Roboto', 'sans-serif'],
  adjustFontFallback: 'Arial',
});

/** Caps-only display face: H1/H2, hero lines, section titles (short strings only). */
export const escargoth = localFont({
  src: [{ path: './fonts/escargoth.woff2', weight: '400', style: 'normal' }],
  variable: '--font-escargoth',
  display: 'swap',
  preload: true,
  adjustFontFallback: 'Times New Roman',
});

/** Blackletter: the brand name and 1–3-word accents only. The header logo is an SVG (no FOUT). */
export const blackRockie = localFont({
  src: [{ path: './fonts/black-rockie.woff2', weight: '400', style: 'normal' }],
  variable: '--font-black-rockie',
  display: 'swap',
  preload: false,
  adjustFontFallback: 'Times New Roman',
});

export const fontVariables = [poppins.variable, escargoth.variable, blackRockie.variable].join(' ');
